#include <vector>

class Solution {
public:
    int minElevatorRounds(std::vector<int>& requests, int capacity) {
        int n = requests.size();
        return (n + capacity - 1) / capacity;
    }
};

class Solution {
    public int minElevatorRounds(int[] requests, int capacity) {
        int n = requests.length;
        return (n + capacity - 1) / capacity;
    }
}

